/// The help for an unresolvable type: why the dependency loader found no declaration for it, when it tried, or
/// `otherwise`.
pub(super) fn unresolved_type_help(
    type_name: &str,
    file: &Utf8Path,
    ctx: &ResolutionContext,
    otherwise: &str,
) -> String {
    let reason = ctx.dependencies.as_ref().and_then(|layer| {
        let (head, rest) = type_name.split_once('.').map_or((type_name, None), |(head, rest)| (head, Some(rest)));
        let binding = ctx.import_map.find_import(file, head)?;
        let name = match (binding.exported_name.as_str(), rest) {
            ("*", Some(rest)) => rest.to_owned(),
            ("*", None) => return None,
            (exported, Some(rest)) => format!("{exported}.{rest}"),
            (exported, None) => exported.to_owned(),
        };
        layer.unresolved_reason(file.parent()?, &binding.specifier, &name)
    });
    match reason {
        Some(reason) => format!("Dependency types are loaded, but for '{type_name}' {}.", reason.describe()),
        None => otherwise.to_owned(),
    }
}

/// What a name used in `file` is bound to, for deciding whether it may take a builtin meaning: a project-local
/// `ReactNode` or `Partial`, or one imported from some other package, is that declaration, not React's or TypeScript's.
#[derive(Debug, PartialEq, Eq)]
pub(super) enum NameBinding {
    /// Declared in `file`.
    Local,
    /// Imported in `file` (for a qualified name, its namespace is) from this specifier.
    Imported(String),
    /// Neither: a global, such as TypeScript's lib types or React's ambient namespace.
    Unbound,
}

pub(super) fn name_binding(name: &str, file: &Utf8Path, ctx: &ResolutionContext) -> NameBinding {
    deps::record(file);
    let head = name.split('.').next().unwrap_or(name);
    if head == name && ctx.named_types.is_declared_at(file, name) {
        return NameBinding::Local;
    }
    match ctx.import_map.find_import(file, head) {
        Some(import) => NameBinding::Imported(import.specifier.clone()),
        None => NameBinding::Unbound,
        DiagnosticSeverity::Info
    } else {
        DiagnosticSeverity::Warning
    };
    state.diagnostics.push(Diagnostic {
        severity,
        message: format!(
            "Cannot resolve type '{}' in '{}'{} — it will appear as an unexpanded named reference",
            name, consuming_file, location_note
        ),
        file: Some(consuming_file.to_string()),
        line: None,
        column: None,
        help: Some(super::unresolved_type_help(
            name.as_str(),
            consuming_file,
            ctx,
            "Check that the package is installed and its types are resolvable.",
        )),
        code: DiagnosticCode::UnresolvableImport,
        affects: Vec::new(),
    });
    PropType::Named { name: name.clone(), args: resolved_args }
}

/// A referenced alias whose expansion is `unevaluated` — it holds a conditional or mapped type the resolver can't
/// evaluate, or an alias named for that reason — shows as its name with its arguments as written
/// (`StyleProp<MantineSpacing>`), the way TypeScript prints it, rather than as that type's source text. An object
/// expansion stays: its fields still read, and only the unevaluated field shows source.
/// A generic alias with `args` bound, its omitted parameters at their defaults. An alias that is a conditional over a bare
/// type parameter (`type Exclude<T, U> = T extends U ? never : T`) distributes over the members of the argument bound to
    // (re-exports, barrel files) — surface that resolved location when it differs,
    // since "Cannot resolve X in file A" is confusing if X actually lives in file B.
    let location_note = super::unresolved_location_note(type_name, consuming_file, &canonical_file, &canonical_name);
    state.diagnostics.push(Diagnostic {
        severity: DiagnosticSeverity::Warning,
        message: format!("Cannot resolve type '{}' in '{}'{}", type_name, consuming_file, location_note),
        file: Some(consuming_file.to_string()),
        line: None,
